import { type PzzConfig, slugify, type Tool } from "./config.ts";

const GENERATED =
  "<!-- Generated by scripts/generate.ts from pzz.json — do not edit by hand. -->";

// Lowercases a leading capitalized word, but keeps acronyms such as "README" intact.
function lowerFirst(text: string): string {
  const word = text.match(/^[A-Z][a-z]/);
  return word ? text.charAt(0).toLowerCase() + text.slice(1) : text;
}

const READING: Record<Tool["source"], string> = {
  llms: "The canonical page is the tool's `llms.txt` index. Read it first, then follow the links it gives for the details the task needs.",
  meta: "The tool has no `llms.txt`. Use the summary above, then open the canonical page for the details the task needs.",
  docs: "The tool has no `llms.txt` and no usable summary. Open the canonical page with the `chrome-devtools` MCP (`navigate`, then read the page) and take only what the task needs.",
};

export function renderToolbox(config: PzzConfig): string {
  return [
    "# Frontend toolbox",
    "",
    "Preferred tools for UI/frontend work. Pick the row matching the task, then open its canonical page.",
    "",
    "| Task | Tool | Canonical page | Source |",
    "| --- | --- | --- | --- |",
    ...config.tools.map(
      (t) => `| ${t.task} | ${t.name} | ${t.url} | ${t.source} |`,
    ),
    "",
    "## Details",
    "",
    ...config.tools.map(
      (t) =>
        `- **[${t.name}](${t.url})** — ${t.task}${t.desc ? `. ${t.desc}` : ""}`,
    ),
    "",
    GENERATED,
    "",
  ].join("\n");
}

export function skillName(tool: Tool): string {
  return slugify(tool.name);
}

export function renderSkill(tool: Tool, docUrl: string): string {
  const summary = tool.desc ? `${tool.desc}\n\n` : "";
  return `---
name: ${skillName(tool)}
description: Use for ${lowerFirst(tool.task)}, with ${tool.name}.
---

# ${tool.name}

${summary}Canonical page: ${tool.url}

${READING[tool.source]}

Full toolbox: \`${docUrl}\`.

${GENERATED}
`;
}
